FuncDef.Code:
float opRevolutionLNorm_LengthLNorm2(in vec2 v, in float power)
{
    // debug
    //return length(v);

    vec2 vpow = pow(abs(v),vec2(power));
    return pow(vpow.x + vpow.y, abs(1.0/power));
}

void opRevolutionLNorm(inout vec3 p, in float radius, in float lNormPower)
{
    g_shapeLoop = atan(p.z, p.x);

    p.xz = vec2(opRevolutionLNorm_LengthLNorm2(p.xz, lNormPower) - radius, p.y);
}
